const $=(q,r=document)=>r.querySelector(q),$$=(q,r=document)=>[...r.querySelectorAll(q)],esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state,session,version,kasCatalog,proof;
const supplierFor=id=>state?.supplierProfile?.id===id?{...state.supplierProfile,name:esc(state.supplierProfile.name),initials:esc(state.supplierProfile.initials)}:fixtureSupplierFor(id);
// Retire the old role-switching cache; never use browser storage as authorization.
localStorage.removeItem('vle-dealroom-review-v1');
async function refresh(){const r=await fetch('/api/bootstrap',{cache:'no-store'});if(!r.ok)throw Error('Unable to load the exchange.');apply(await r.json());}
function apply(data){proof=data.proof||{organizations:[],lots:[]};state=data.state;session=data.session;version=data.version;kasCatalog={...data.kasandrinos,organizations:proof.organizations,lotProofs:proof.lots,proof:proof.organizations.find(o=>o.slug==='kasandrinos')};setLots(data.lots);brand.email=session.email||'';brand.name=session.email?session.email.split('@')[1]:'Your brand';brand.person=session.name||'Brand buyer';}
async function mutate(action,data={}){const r=await fetch('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,data,version})});const value=await r.json();if(!r.ok)throw Error(value.error||'Please try again.');apply(value);}

let search='',filter='All ingredients',onlyMatch=false,modal={};let focusBack=null,pdfUrl=null;
const save=()=>{},money=n=>Number(n).toFixed(2),route=()=>location.pathname.replace(/\/$/,'')||'/',lotURL=l=>'/lots/'+l.id,roomURL=d=>'/deals/room?id='+d.id;
const icon=(n='arrow')=>{const paths={arrow:'M5 12h14m-6-6 6 6-6 6',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',home:'m3 10 9-7 9 7v10H3zM9 20v-7h6v7',box:'m3 7 9-4 9 4-9 5-9-5zm0 0v10l9 4 9-4V7m-9 5v9',chat:'M21 11a9 8 0 0 1-9 8H6l-4 3 1-6a8 8 0 0 1-1-5 9 8 0 0 1 19 0Z',file:'M14 3H5v18h14V8l-5-5zm0 0v5h5M8 12h8m-8 4h6',check:'m5 12 4 4L19 6',plus:'M12 5v14M5 12h14',lock:'M6 10h12v11H6zM8 10V6a4 4 0 0 1 8 0v4',people:'M9 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm-6 9v-3a6 6 0 0 1 12 0v3m1-16a4 4 0 0 1 0 8m2 3a5 5 0 0 1 3 5',out:'M9 3H3v18h6m5-14 5 5-5 5m-6-5h11'};return `<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(paths[n]||paths.arrow).split('|').map(d=>`<path d="${d}"/>`).join('')}</svg>`};
const ex=()=>'<span class="example">EXAMPLE</span>',badge=(x,c='lavender')=>`<span class="badge ${c}">${x}</span>`,def=(x)=>`<span class="default-note">${esc(x)} <b>default, for review</b></span>`;
const action=(text,a,extra='',cls='primary')=>`<button class="${cls}" data-action="${a}" ${extra}>${text}${icon()}</button>`,link=(text,url,cls='button')=>`<a class="${cls}" href="${url}" data-nav>${text}${icon()}</a>`;
const field=(label,name,value='',type='text',extra='')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select=(label,name,options,value='',placeholder='Choose')=>`<label class="field"><span>${label}</span><select name="${name}"><option value="">${placeholder}</option>${options.map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`;
const defaults=(open=false)=>`<details class="defaults"${open?' open':''}><summary>Evidence and sourcing boundaries</summary><div class="defaults-content"><p>Original lot reports and commercial terms have separate sign-in requirements. A source report is not a certification or a guarantee that a lot meets your targets. Supplier-reported values and buyer evaluations are distinct from authenticated laboratory evidence.</p><p>Private sourcing notes stay in the buyer account. Explicitly shared summaries reach suppliers in the matching category. Conversations are restricted to their participants. Soft holds do not form a purchase contract; contract and payment happen off-platform.</p><p>Live TECRID authentication and laboratory ordering require an authorized integration. Kasandrinos’s authorized team can receive sourcing inquiries.</p></div></details>`;
function reviewBar(){return `<div class="reviewbar"><div><span class="review-dot"></span><strong>VLE · The Ingredient Exchange</strong><span>Real suppliers. Lot-linked evidence.</span></div>${session.signedIn?`<span class="session-email">${esc(session.email)}</span><button data-action="sign-out" class="review-reset">Sign out</button><a href="/team" data-nav class="review-reset">${esc(session.team?.name||'Account & team')}</a>`:link('Sign in','/email-sign-in','text-link')}</div>`}
function nav(){const r=route(),signed=['brand','supplier'].includes(state.role),home=state.role==='supplier'?'/workspace':'/brand';const links=signed?[[home,'Overview','home'],['/suppliers','Find lots','search'],['/requests','Requests','people'],['/deals','Conversations','chat'],['/notifications','Notifications','file'],['/team','Account & team','people'],['/proof','Proof & releases','file'],...(state.role==='supplier'?[['/workspace/documents','Lots and documents','file']]:[]),['/resources','Resources','box']]:[['/','Home','home'],['/suppliers','Find lots','search'],['/resources','Resources','box']];return `<aside class="sidebar"><a class="logo" href="/" data-nav aria-label="VLE home">vle<span>.</span></a><p class="logo-sub">Verified Lot Exchange</p><nav aria-label="Main navigation"><a href="/how-it-works" data-nav class="guide-chip ${r==='/how-it-works'?'selected':''}">${icon('box')}How does this work?</a>${links.map(([url,title,ico])=>`<a href="${url}" data-nav class="${r===url?'selected':''}">${icon(ico)}${title}${url==='/deals'&&visibleDeals().length?`<span class="nav-count">${visibleDeals().length}</span>`:''}</a>`).join('')}</nav>${session.pilotController?`<section class="pilot-switch" aria-label="Pilot account switch"><span class="eyebrow">YOUR PILOT ACCOUNTS</span><p>Active: ${esc(session.team?.name||'Personal workspace')}</p><button data-pilot-account="karen-buyer-team" ${session.team?.id==='karen-buyer-team'?'aria-pressed="true"':'aria-pressed="false"'}>Buyer account</button><button data-pilot-account="kasandrinos-team" ${session.team?.id==='kasandrinos-team'?'aria-pressed="true"':'aria-pressed="false"'}>Kasandrinos supplier</button><p class="pilot-error" role="alert"></p></section>`:''}<div class="sidebar-bottom"><div class="sidebar-promise">Good ingredients.<br>Real conversations.</div>${signed?`<div class="account"><span class="avatar">${state.role==='brand'?esc(brand.initials):supplierFor(state.supplier).initials}</span><div><strong>${esc(session.team?.name||(state.role==='brand'?brand.name:supplierFor(state.supplier).name))}</strong><small>${state.role==='brand'?'Brand buyer':'Ingredient supplier'}${state.supplier===state.supplierProfile?.id?' · Private workspace':''}</small></div></div>`:link('Sign in','/email-sign-in','button orange')}<a class="sidebar-help" href="/design-system" data-nav>Evidence and access →</a></div></aside>`}
function topbar(){return `<header class="topbar"><span>${state.role==='brand'?'BRAND WORKSPACE':state.role==='supplier'?'SUPPLIER WORKSPACE':'THE INGREDIENT EXCHANGE'}</span><div>${evidenceNotificationLink(session)}${!session.signedIn?link('Sign in','/email-sign-in','text-link'):badge('Signed in','neutral')}${state.role==='brand'?link('Post a Request','/requests/new','button orange small'):state.role==='supplier'?link('Manage lots','/workspace/documents','button small'):link('For suppliers','/workspace','button small')}</div></header>`}
function visibleDeals(){return state.deals.filter(d=>canSeeDeal(state,d))}
function supplierSetup(){return `<section class="panel sign-in"><span class="eyebrow">YOUR SUPPLIER WORKSPACE</span><h1>Meet your next buyer.</h1><p>Signed in as ${esc(session.email)}. Set up your own private workspace.</p><form data-form="supplier-profile">${field('Company name','name',state.supplierProfile?.name||'','text','required minlength="2" maxlength="120" autocomplete="organization"')}${select('Ingredient category','category',categories,state.supplierProfile?.category||'')}<button type="submit" class="orange full">Create my supplier workspace ${icon()}</button></form><p class="fine">Your profile stays private. New supplier listings, real lot uploads and cross-account trading are not connected yet. Creating a profile does not claim an existing supplier or grant access to its documents.</p></section>`}
function needRole(role){if(role==='supplier'&&session.canManageStorefront)return `<section class="gate"><span class="eyebrow">KASANDRINOS</span><h1>Your brand. Your storefront.</h1><p>Shape the imagery, story, featured lots and layout, then publish when you are ready.</p>${link('Open storefront studio','/workspace/storefront','button orange')}</section>`;if(role==='supplier'&&session.signedIn)return state.supplierProfile?`<section class="gate"><h1>Your supplier workspace is ready.</h1>${action('Open my supplier workspace','workspace','data-role="supplier"','orange')}</section>`:supplierSetup();return `<section class="gate"><span class="gate-icon">${icon('lock')}</span><span class="eyebrow">${role==='brand'?'FOR BRANDS':'FOR SUPPLIERS'}</span><h1>${role==='brand'?'Your sourcing, in one place.':'Meet the brands looking for you.'}</h1><p>${role==='brand'?'Sign in with your company email to open full COAs and manage your sourcing workspace.':'Use your own email to create a private supplier workspace.'}</p>${session.signedIn&&role==='brand'&&session.canBuy?action('Open brand workspace','workspace','data-role="brand"','orange'):link('Continue to sign-in','/email-sign-in?as='+role,'button orange')}${session.canReview?`<div class="demo-gate"><strong>Owner review</strong>${action('Review EXAMPLE '+role,'role',`data-role="${role}"`,'secondary')}</div>`:''}</section>`}
function title(k,h,p='',buttons=''){return `<div class="page-title"><div><span class="eyebrow">${k}</span><h1>${h}</h1>${p?`<p>${p}</p>`:''}</div>${buttons}</div>`}
function roomCard(d){const l=allLots(state).find(x=>x.id===d.lot),s=supplierFor(d.supplier),n=nextAction(d);return `<a class="room-card" href="${roomURL(d)}" data-nav><div class="room-card-top"><span class="avatar ${state.role==='supplier'?'orange-soft':''}">${state.role==='supplier'?'EF':s.initials}</span><div><h3>${state.role==='supplier'?brand.name:s.name}</h3><p>${l.product}</p></div>${icon()}</div><div class="room-card-meta">${badge(stages[d.stage],d.stage===6?'green':'lavender')}<span>${d.lot}</span></div><p class="room-last">“${esc(d.events.filter(e=>e.kind==='message').at(-1)?.text||d.events.at(-1).text)}”</p><div class="room-next"><span class="${n.role===state.role?'attention-dot':'quiet-dot'}"></span>${n.role===state.role?'Your next step: ':n.role?'Waiting on '+(n.role==='brand'?'brand':'supplier')+': ':''}<strong>${n.text}</strong></div></a>`}
function lotCard(l){return kasLotCard({...l,proof:proof.lots.find(x=>x.id===l.id)},kasCatalog)}
function home(){return `<div class="landing"><section class="home-hero home-search-hero"><div><span class="eyebrow">THE INGREDIENT EXCHANGE</span><h1>Know what’s in<br>the lot <em>before<br>you buy it.</em></h1><p>Find your ingredient. Meet the supplier.<br>See the lot evidence for yourself.</p><form data-form="search" class="search">${icon('search')}<input name="q" aria-label="Search ingredients or suppliers" placeholder="Ingredient, supplier or application"><button class="orange" type="submit">Find lots ${icon()}</button></form><small>Browse freely. Sign in for evidence and commercial terms.</small></div></section><section class="home-next"><div class="hero-room hero-supplier"><div class="hero-room-header"><img src="/assets/kasandrinos-logo.png" alt="Kasandrinos logo"><span>Our first supplier<br><small>Laconia, Greece</small></span>${badge('Lot-linked COAs','yellow')}</div>${productPhoto('/assets/kas-250ml.png','Official Kasandrinos olive oil bottle photograph','hero-supplier-product')}<h2>Meet Kasandrinos.</h2><p>Organic extra virgin olive oil.<br>Six documented lots. Original reports.</p>${supplierProofStrip(kasCatalog)}${link('Explore Kasandrinos','/organizations/kasandrinos#proof-wall','button orange full')}</div><div class="paths"><a href="/brand" data-nav><span class="path-icon">${icon('search')}</span><div><h2>Find your next supplier.</h2><p>Search lots, post a Request and start a conversation.</p></div>${icon()}</a><a href="/workspace" data-nav><span class="path-icon orange-soft">${icon('people')}</span><div><h2>Meet your next buyer.</h2><p>Answer relevant demand and move deals forward.</p></div>${icon()}</a></div></section><div class="section-heading"><div><span class="eyebrow">A PLACE TO START</span><h2>Real conversations start with a lot.</h2></div>${link('Browse lots','/suppliers','text-link')}</div><div class="lot-grid">${allLots(state).map(lotCard).join('')}</div><p class="fine">Kasandrinos is our first supplier. Every listed lot has a matching source report. More suppliers will appear as they are onboarded.</p></div>`}
function limitsStrip(){return `<div class="limits-strip"><span>${icon('check')} MY SAVED LIMITS</span>${analytes.map((a,i)=>`<span>${a} <strong>≤ ${state.limits[i]}</strong></span>`).join('')}<span>mg/kg · as sold</span><button class="text-link" data-action="limits">Edit</button></div>`}
function brandHome(){if(state.role!=='brand')return needRole('brand');return `${title('YOUR SOURCING DESK','Good ingredients. Better connections.','Explore documented lots and read the original supplier evidence.')} ${limitsStrip()}<div class="dashboard-grid"><section><div class="section-heading"><h2>Your Deal Rooms <span class="count">${visibleDeals().length}</span></h2>${link('View all','/deals','text-link')}</div><div class="room-grid">${visibleDeals().length?visibleDeals().slice(0,2).map(roomCard).join(''):empty('Your next conversation starts with a lot.','Explore Kasandrinos. Conversations will open after its supplier account is connected.','/suppliers','Find lots')}</div></section><aside class="request-callout"><span class="callout-icon">${icon('people')}</span><span class="eyebrow">LET SUPPLIERS COME TO YOU</span><h2>Tell them what<br>you’re looking for.</h2><p>Post one sourcing brief. Hear from suppliers in the right category.</p>${link('Post a Request','/requests/new','button orange')}</aside></div><div class="section-heading"><h2>Your Requests</h2>${link('Manage Requests','/requests','text-link')}</div>${requestRows(state.requests.filter(r=>r.brand===brand.id))}<div class="section-heading"><div><span class="eyebrow">REAL SUPPLIER EVIDENCE</span><h2>Lots worth a conversation.</h2></div>${link('Find more lots','/suppliers','text-link')}</div><div class="lot-grid">${allLots(state).filter(l=>l.real||match(l,state.limits)==='Meets your limits').map(lotCard).join('')}</div>${def('Company email qualifies a brand buyer. Verified badges come later.')}`}
const empty=(h,p,url,label)=>`<div class="empty"><h3>${h}</h3><p>${p}</p>${url?link(label,url,'button'):''}</div>`;
function requestRows(rs){return `<div class="request-list">${rs.length?rs.map(r=>`<article class="request-row"><span class="request-symbol">${icon('people')}</span><div><div class="eyebrow">${state.role==='supplier'?brand.name+' · EXAMPLE':r.id}</div><h3>${esc(r.ingredient)}</h3><p>${r.quantity} ${r.unit} · ${esc(r.destination)} · Needed by ${r.date}</p></div><div>${badge(r.status,r.status==='Open'?'green':'neutral')}<p class="fine">${r.responses.length} response${r.responses.length===1?'':'s'}</p></div>${action(state.role==='supplier'?'View Request':'Open Request','request-detail',`data-id="${r.id}"`,'secondary small')}</article>`).join(''):empty('No open Requests here yet.','Requests are shown only to suppliers in their matching category.')}</div>`}
function supplierHome(){if(state.role!=='supplier')return needRole('supplier');if(state.supplier===state.supplierProfile?.id)return personalSupplierHome();const s=supplierFor(state.supplier),ds=visibleDeals(),rs=state.requests.filter(r=>r.category===s.category&&r.status==='Open');return `${title('YOUR SUPPLIER DESK',s.real?'Your next buyer starts here.':'Make your next connection.',s.name+(s.real?' · Real supplier, lot-linked evidence':' · EXAMPLE supplier'))}<div class="supplier-stats"><div><span>ACTIVE DEAL ROOMS</span><strong>${ds.length.toString().padStart(2,'0')}</strong><small>Conversations with a next step</small></div><div><span>MATCHING REQUESTS</span><strong>${rs.length.toString().padStart(2,'0')}</strong><small>Brands looking for ${s.category.toLowerCase()}</small></div><div><span>COA VIEWS</span><strong>${state.views.filter(v=>v.supplier===s.id).length.toString().padStart(2,'0')}</strong><small>Signed-in brand buyers</small></div></div><div class="dashboard-grid supplier-grid"><section><div class="section-heading"><h2>Brands looking for you</h2>${badge(s.category,'neutral')}</div>${requestRows(rs)}${def('Requests are visible to every supplier in the matching category.')}<div class="section-heading"><h2>Keep the conversation moving</h2>${link('All Deal Rooms','/deals','text-link')}</div><div class="room-grid">${ds.length?ds.map(roomCard).join(''):empty('No conversations yet.','Reply to a Request with a COA-backed lot to begin.')}</div>${def('Reply to Requests, COA views or inquiries. No cold messaging.')}</section><aside><div class="panel viewer-panel"><div class="panel-title"><span class="icon-tile lavender">${icon('file')}</span><h3>Who opened your COAs</h3></div>${state.views.filter(v=>v.supplier===s.id).length?state.views.filter(v=>v.supplier===s.id).slice(-3).reverse().map(v=>`<div class="viewer"><span class="avatar orange-soft">B</span><div><strong>${esc(v.company||brand.name)}</strong><p>${esc(v.person)}${v.realView?" · Signed-in buyer":" · EXAMPLE"}</p>${v.email?`<small>${esc(v.email)}</small>`:""}<small>${esc(v.lot)}<br>${esc(v.time)}</small></div></div>`).join(''):'<p class="muted">Brand COA views will appear here with the person, company and lot.</p>'}</div>${s.real?`<article class="draft-card supplier-proof-card"><img src="/assets/kasandrinos-bottle.png" alt="Official Kasandrinos olive oil bottle"><div><span class="eyebrow">FIRST REAL SUPPLIER</span><h3>Kasandrinos</h3><p>Organic Extra Virgin Olive Oil</p>${badge('Real reports matched to lots','yellow')}<small>Six lots identified in published reports.</small>${link('View supplier','/suppliers/kasandrinos','text-link')}</div><div class="supplier-card-proof">${supplierProofStrip(kasCatalog)}</div></article>`:s.id==='aegean'?`<a class="draft-card" href="/workspace/documents" data-nav><span class="icon-tile orange-soft">${icon('file')}</span><div><span class="eyebrow">YOUR EXAMPLE DRAFT</span><h3>Early harvest olive oil</h3>${badge(state.draft.published?'EXAMPLE lot published':state.draft.coa?'Values awaiting confirmation':'Awaiting COA','yellow')}<small>Review evidence before publication.</small></div>${icon()}</a>`:''}<div class="panel"><h3>Lab values to confirm</h3><p>${s.real?'Original reports are attached. Numerical values await supplier confirmation.':state.draft.confirmed?'Your EXAMPLE values are confirmed.':state.draft.coa?'Four EXAMPLE extracted values need review.':'Load the fictional lab PDF to try the review flow.'}</p>${link('Review lots and documents','/workspace/documents','text-link')}</div></aside></div>`}
function personalSupplierHome(){const profile=state.supplierProfile,rs=state.requests.filter(r=>r.category===profile.category&&r.status==='Open');return `${title('YOUR SUPPLIER DESK','Your next connection starts here.',esc(profile.name))}<div class="notice"><strong>Your email is confirmed. Your workspace is private.</strong><p>${esc(session.email)} · ${esc(profile.category)}. You have no published lots or buyer conversations yet.</p></div><div class="dashboard-grid supplier-grid"><section><div class="section-heading"><h2>Requests in your category</h2>${badge(esc(profile.category),'neutral')}</div>${requestRows(rs)}<p class="fine">Matching brand Requests will appear here when shared sourcing is connected.</p>${empty('No Deal Rooms yet.','Your own inquiries and eligible Request responses will appear here. No cold messaging.')}</section><aside><div class="panel"><h3>Your lots and documents</h3><p>No lots have been submitted. Products stay private until a COA matches the specific lot and the supplier confirms its values.</p>${link('View my lot workspace','/workspace/documents','button orange full')}</div><div class="panel"><h3>Who opened your COAs</h3><p>No COA views yet. Another supplier’s buyer activity and drafts are never shared with your account.</p></div></aside></div><p class="fine">Your submissions stay private during review. Reply to relevant shared requests using a reviewed lot report.</p>`}
function discovery(){const q=new URLSearchParams(location.search).get('q')||search;let ls=allLots(state).filter(l=>(filter==='All ingredients'||l.category===filter)&&(!q||(l.product+' '+supplierFor(l.supplier).name+' '+l.category).toLowerCase().includes(q.toLowerCase())));return `${title('FIND YOUR NEXT SOURCE','Start with a lot. Meet the supplier.','Every listed lot has a matching COA. Kasandrinos value confirmation is pending.')}${kasFeature(kasCatalog)}<form data-form="search" class="search directory-search">${icon('search')}<input name="q" value="${esc(q)}" placeholder="Ingredient or supplier" aria-label="Search ingredients or suppliers"><button type="submit" class="primary">Search</button></form><div class="filterbar"><div class="category-tabs">${['All ingredients',...new Set(allLots(state).map(l=>l.category))].map(c=>`<button class="${filter===c?'active':''}" data-action="filter" data-category="${c}">${c}</button>`).join('')}</div><span class="fine">Value comparisons await supplier confirmation.</span></div><p class="muted results-count">${ls.length} documented lots · Kasandrinos ${q?`matching “${esc(q)}”`:''}</p><div class="lot-grid">${ls.map(lotCard).join('')}</div>${!ls.length?empty('Let suppliers know what you need.','Post a Request with your application, quantity and timing.','/requests/new','Post a Request'):''}<p class="fine">Kasandrinos is currently our only listed supplier. Every lot links to a matching source report; availability and terms await supplier confirmation.</p>`}
function evidenceTable(l,limits=null){return `<div class="table-scroll"><table class="data-table"><thead><tr><th>Analyte</th><th>Confirmed result</th>${limits?'<th>Your limit</th>':''}<th>Basis</th></tr></thead><tbody>${l.analytes.map((a,i)=>`<tr><th>${a}</th><td>${l.values[i].q==='<'?'&lt; ':''}${l.values[i].value} <span>mg/kg</span>${l.values[i].rl!=null?`<small>Reporting limit ${l.values[i].rl} mg/kg</small>`:''}</td>${limits?`<td>≤ ${limits[i]} mg/kg</td>`:''}<td>${l.basis}</td></tr>`).join('')}</tbody></table></div>`}
function lotPage(l){return l?.real?kasLotPage({...l,proof:proof.lots.find(x=>x.id===l.id)},kasCatalog,session):empty('Lot unavailable.','Only lots with matching COAs appear here.','/suppliers','Browse lots')}
function requestComposer(){if(state.role!=='brand')return needRole('brand');return `${title('POST A REQUEST','One brief. The right suppliers.','Tell suppliers what you need, then keep their responses in your Deal Rooms.')}<div class="composer-grid"><form data-form="post-request" class="panel composer"><h2>What are you sourcing?</h2><div class="form-grid">${select('Ingredient category','category',categories,'Olive oil')}${field('Ingredient','ingredient','Organic extra virgin olive oil','text','required')}${field('Quantity','quantity',500,'number','min="1" required')}${select('Unit','unit',['kg','L','tonnes'],'L')}${field('Needed by','date','2026-11-30','date','required')}${field('Destination','destination','Netherlands','text','required')}</div>${field('Intended application','use','A new line of dressings','text','required')}<h3>Your contaminant limits</h3><p class="fine">mg/kg · as sold. Edit these for this Request. “Total arsenic” is not inorganic arsenic.</p><div class="form-grid">${analytes.map((a,i)=>field(a,'limit'+i,state.limits[i],'number','min="0" step="any" required')).join('')}</div><label class="field"><span>Other requirements</span><textarea name="needs" rows="3" placeholder="Origin, certification, packaging…">Organic, Greek origin, foodservice packaging</textarea></label><div class="form-actions">${link('Cancel','/requests','text-link')}<button class="orange" type="submit">Post EXAMPLE Request ${icon()}</button></div><p class="fine">Saved to your signed-in EXAMPLE workspace. No real supplier is contacted.</p></form><aside><div class="panel request-preview"><span class="avatar orange-soft">${esc(brand.initials)}</span><h2>${esc(brand.name)}</h2><p>${esc(session.email)} · Brand buyer</p>${ex()}<hr><h3>Who will see this?</h3><p>Every supplier in the matching ingredient category can read and respond to this Request.</p>${def('Category-wide Request visibility.')}<hr><h3>What happens next?</h3><ol><li>A supplier answers with an eligible lot.</li><li>Your shared Deal Room opens.</li><li>Agree on a sample and take the next step.</li></ol><p class="fine">A supplier needs a matching lot COA to respond. No unsolicited messaging.</p></div></aside></div>`}
function requestsPage(){if(!['brand','supplier'].includes(state.role))return needRole('brand');const s=supplierFor(state.supplier),rs=state.requests.filter(r=>state.role==='brand'?r.brand===brand.id:r.category===s.category&&r.status==='Open');return `${title(state.role==='brand'?'YOUR SOURCING BRIEFS':'BRAND DEMAND',state.role==='brand'?'Let the right suppliers find you.':'A need you can answer.',state.role==='brand'?'Track responses and continue each conversation in its Deal Room.':'Open Requests in your ingredient category. Respond with a COA-backed lot.',state.role==='brand'?link('Post a Request','/requests/new','button orange'):'')}${requestRows(rs)}${def('Every supplier in the matching category can see a Request. No cold messaging.')}`}
function dealsPage(){if(!['brand','supplier'].includes(state.role))return needRole('brand');return `${title('SHARED CONVERSATIONS','Every lot has a next step.','The same room, messages and deal record for both sides.')}<div class="room-grid">${visibleDeals().map(roomCard).join('')||empty('No Deal Rooms yet.','Open a lot COA, start an inquiry or answer a relevant Request.','/suppliers','Find a lot')}</div>`}
function stageRail(d){return `<ol class="stage-rail">${stages.map((t,i)=>`<li class="${i<d.stage?'done':i===d.stage?'current':''}"><span>${i<d.stage?'✓':i+1}</span>${t}</li>`).join('')}</ol>`}
function timelineEvent(e,d){const system=e.kind!=='message'&&e.kind!=='attachment',who=e.actor==='brand'?brand.name:supplierFor(d.supplier).name;return system?`<div class="timeline-event"><span class="event-dot ${e.kind==='qualified'||e.kind==='test'?'lavender':''}">${icon(e.kind==='quote'?'file':'check')}</span><div><span class="event-meta">${who} <time>${e.time}</time></span><p>${esc(e.text)}</p></div></div>`:`<article class="message ${e.actor===state.role?'mine':''}"><div class="message-author"><span class="avatar ${e.actor==='brand'?'orange-soft':'teal-soft'}">${e.actor==='brand'?'EF':supplierFor(d.supplier).initials}</span><strong>${who}</strong><time>${e.time}</time></div><div class="message-bubble">${esc(e.text)}${e.file?`<button class="attachment" data-action="download-attachment" data-deal="${d.id}" data-name="${e.file}">${icon('file')}${esc(e.file)} · EXAMPLE ↓</button>`:''}</div></article>`}
function roomPage(id){const d=state.deals.find(x=>x.id===id);if(!canSeeDeal(state,d))return empty('This room belongs to its participants.','Sign in with the participating account to open your EXAMPLE workspace.','/deals','Your Deal Rooms');const l=allLots(state).find(x=>x.id===d.lot),s=supplierFor(d.supplier),n=nextAction(d);return `<div class="crumb">${link('Deal Rooms','/deals','text-link')}<span>/</span>${d.id}</div><div class="deal-title"><div class="pair-avatars"><span class="avatar orange-soft">EF</span><span class="avatar teal-soft">${s.initials}</span></div><div><span class="eyebrow">SHARED DEAL ROOM · EXAMPLE</span><h1>${brand.name} <span>×</span> ${s.name}</h1><p>${l.product} <span>·</span> ${l.id}</p></div>${badge(stages[d.stage],d.stage===6?'green':'yellow')}</div>${stageRail(d)}<div class="deal-layout"><section class="conversation panel"><div class="conversation-heading"><h2>Conversation & activity</h2><span>${d.events.length} updates</span></div><div class="timeline">${d.events.map(e=>timelineEvent(e,d)).join('')}</div><form data-form="message" data-id="${d.id}" class="message-composer"><label for="message-text" class="sr">Message to ${state.role==='brand'?s.name:brand.name}</label><textarea id="message-text" name="text" rows="2" placeholder="${state.role==='brand'?'Ask a question or share what you need…':'Reply to the brand and keep things moving…'}" required maxlength="1500"></textarea><div>${action('Attach EXAMPLE file','attach',`data-id="${d.id}"`,'text-link')}<button class="orange small" type="submit">Send EXAMPLE ${icon()}</button></div><span class="fine">Saved to this shared demo timeline. No real message is sent.</span></form></section><aside class="deal-sidebar"><section class="next-panel"><span class="eyebrow">${n.role===state.role?'YOUR NEXT ACTION':n.role?'WAITING ON '+n.role.toUpperCase():'DEAL MILESTONE'}</span><h2>${n.text}</h2><p>${d.stage===6?'Your EXAMPLE soft hold is confirmed. Continue to contract and payment off the platform.':n.role===state.role?'Take the next step. The other side will see the update in this room.':'You can send a message while the other side completes this step.'}</p>${n.role===state.role&&n.action?action(n.text,'step',`data-id="${d.id}" data-step="${n.action}"`,'orange full'):''}${d.stage===2&&!d.costAgreed?costControl(d):''}${d.stage>=5?def('Soft hold only. No payment. Contract and payment happen off the platform.'):''}</section><section class="panel deal-record"><h3>Deal record</h3><dl><div><dt>Lot</dt><dd>${link(l.id,lotURL(l),'text-link')}</dd></div><div><dt>Intended quantity</dt><dd>${d.brief.quantity} ${d.brief.unit}</dd></div><div><dt>Destination</dt><dd>${esc(d.brief.destination)||'To agree'}</dd></div><div><dt>Pricing</dt><dd>${d.quote?`EXAMPLE USD ${money(d.quote.price)} / ${l.unit}`:'Supplier to share'}</dd></div>${d.quote?`<div><dt>MOQ / lead</dt><dd>${d.quote.moq} ${l.unit} / ${esc(d.quote.lead)}</dd></div><div><dt>Quote valid through</dt><dd>${d.quote.valid}</dd></div><div><dt>Freight / tax</dt><dd>${esc(d.quote.freight)} / excluded</dd></div>`:''}<div><dt>Sample</dt><dd>${d.sample?`${d.sample.quantity} ${d.sample.unit} · ${d.sample.shipped?'shipped':'requested'}`:'Not requested'}</dd></div><div><dt>TECRID</dt><dd>${d.test?'EXAMPLE result attached':'Pending'}</dd></div><div><dt>Reservation</dt><dd>${d.reservation?`${d.reservation.status}: ${d.reservation.quantity} ${l.unit} until ${d.reservation.until}`:'Not requested'}</dd></div></dl>${state.role==='brand'?action('Open lot COA','coa',`data-lot="${l.id}"`,'secondary full small'):link('Manage source lot','/workspace/documents','button full small')}</section><section class="panel"><h3>Cost agreement</h3>${costControl(d)}${def('Shipping and verification-test payers are agreed here. No default payer.')}</section><section class="panel"><h3>Brand limits for this deal</h3><div class="compact-limits">${analytes.map((a,i)=>`<div><span>${a}</span><strong>≤ ${d.limits[i]} mg/kg</strong></div>`).join('')}</div><p class="fine">Saved when this deal began. As-sold basis. Qualification is the brand’s decision, not a certification.</p></section></aside></div>`}
function costControl(d){return `${d.costProposal?`<p class="cost-summary">Shipping: <strong>${d.costProposal.shipping}</strong><br>Verification test: <strong>${d.costProposal.testing}</strong></p>${badge(d.costAgreed?'Both sides agreed':'Awaiting '+(d.costProposal.by==='brand'?'supplier':'brand'),d.costAgreed?'green':'yellow')}${!d.costAgreed&&d.costProposal.by!==state.role?action('Agree to these payers','agree-costs',`data-id="${d.id}"`,'primary full small'):''}`:'<p class="muted">No payer agreed yet.</p>'}${d.stage<3?action(d.costProposal?'Propose a change':'Propose who pays','step',`data-id="${d.id}" data-step="costs"`,'text-link'):''}`}
function proofLotPage(id){const original=allLots(state).find(l=>l.id===id);if(original)return lotPage(original);const lot=proof.lots.find(l=>l.id===id);if(!lot)return empty('Lot unavailable.','No public lot is on file.');const supplier=proof.organizations.find(o=>o.id===lot.supplier_id);return `<div class="page-title"><div><span class="eyebrow">LOT EVIDENCE</span><h1>${esc(lot.product)}</h1><p>Supplier lot ${esc(lot.supplier_lot_id)}</p><p>Originating supplier: <a href="/organizations/${esc(supplier?.slug)}" data-nav>${esc(supplier?.name)}</a></p><p>Ingredient code: ${esc(lot.ingredient_code||lot.product_sku||'Awaiting signed identity')}</p></div></div>${mobileProofStrip({...lot,proof:lot},kasCatalog)}${proofWall(lot)}${releaseList(lot,proof.organizations)}`;}
function kasPage(){return kasSupplierPage(kasCatalog,session)}
function documents(){if(state.role!=='supplier')return needRole('supplier');if(state.supplier===state.supplierProfile?.id)return `${title('YOUR LOT WORKSPACE','Evidence comes before a listing.',esc(state.supplierProfile.name))}<div class="panel"><h2>No lots submitted yet</h2><p>Your workspace is private. Document uploads and new supplier listings are not connected yet.</p><p>A product needs a COA matched to its specific lot. Extracted values require supplier confirmation. Certifications are labeled Supplier-reported.</p>${link('Back to my workspace','/workspace','button orange')}</div>`;return kasPage()}
function signIn(){const params=new URLSearchParams(location.search),failed=params.has('error'),intent=params.get('as')==='supplier'?'Supplier':'Brand buyer';return `<section class="sign-in"><a class="logo" href="/" data-nav>vle<span>.</span></a><span class="eyebrow">MEET YOUR NEXT SOURCE</span><h1>Your email.<br>Your next connection.</h1><p>For brand buyers and ingredient suppliers. Use your own email—no ChatGPT account needed.</p>${session.signedIn?`<div class="notice"><strong>Signed in as ${esc(session.email)}</strong><p>${session.canBuy?'Your email is confirmed. Brand-buyer access includes full COAs and lab values.':'Your email is confirmed. Commercial terms are available. Use a company email for brand-buyer evidence access.'}</p></div>${session.pilotController?link('Choose buyer or supplier account','/team','button orange full'):intent==='Supplier'&&!state.supplierProfile?link('Set up my supplier workspace','/workspace','button orange full'):state.supplierProfile?action('Open my supplier workspace','workspace','data-role="supplier"','orange full'):link('Set up my supplier workspace','/workspace','button secondary full')}${session.canManageStorefront?link('Manage Kasandrinos storefront','/workspace/storefront','button orange full'):''}${session.pilotController?link('How does this work?','/how-it-works','button full'):session.canBuy?action('Open brand workspace','workspace','data-role="brand"','primary full'):link('Browse lots','/suppliers','button full')}<button data-action="sign-out" class="text-link">Sign out to use a different email</button>`:`${failed?'<div class="notice" role="alert">This link has expired or has already been used. Request a new sign-in link below.</div>':''}<form data-form="sign-in">${select('I’m here as','workspace',['Brand buyer','Supplier'],intent)}${field('Email address','email','','email','placeholder="you@company.com" autocomplete="email" required')}<button class="orange full" type="submit">Email me a sign-in link ${icon()}</button><p class="fine">New here? Your account is created when you verify your email. Returning? Use the same email. Your link expires in 10 minutes and works once.</p><div id="signin-result" role="status" aria-live="polite"></div></form><p class="fine">Brand buyers use a company email for full COAs and lab values. Commercial terms require sign-in. Suppliers create their own private workspace after confirming their email. Opening a COA records your email and company domain for the owning supplier.</p>`}${def('Anyone signed in with a company email is a brand buyer. A verified badge comes later.')}</section>`}
function resources(){return `${title('RESOURCES','Support for your sourcing decision.','Evidence, research and certification have distinct roles.')}<div class="resource-grid"><article class="panel"><span class="icon-tile lavender">${icon('file')}</span><h2>TECRID</h2><p>Record identity and authentication are distinct from testing, brand qualification and certification. Kasandrinos reports link to TECRID sandbox records for integration testing. Production authentication is not connected; buyer evaluations remain separately labeled.</p><a href="https://tecrid.com/" target="_blank" rel="noreferrer" class="text-link">Official TECRID website ↗</a></article><article class="panel"><span class="icon-tile orange-soft">${icon('box')}</span><h2>Light Labs</h2><p>Participating laboratory, per VLE confirmation. Production issuer status pending verification.</p>${link('View laboratory','/resources/labs/light-labs','text-link')}</article><article class="panel"><h2>Certifications</h2>${badge('Supplier-reported','neutral')}<p>Check the program, issuer, product scope and dates. A COA is not a certificate, and a supplier confirmation is not issuer authentication.</p></article></div>`}
function design(){return `${title('REVIEW REFERENCE','Interaction first.','One shared deal, role-owned actions and visible next steps.')}<div class="swatches">${[['Deep teal','#006e5c'],['Orange','#ff6b19'],['Yellow','#ffd45c'],['Lavender','#eae4fb']].map(([n,c])=>`<div style="background:${c}"><strong>${n}</strong><span>${c}</span></div>`).join('')}</div><div class="panel"><h2>Approved defaults</h2>${defaults()}</div><div class="panel"><h2>Access and identity</h2><p>Signed-out: lot metadata only, no values or PDFs. Brand buyer: confirmed values, full COA and commercial terms. Supplier workspace: its own source-review data and participant Deal Rooms. A COA open records the brand identity in supplier view history.</p><p>Email ownership is verified by a one-use email link and access is checked on the server. Anonymous responses contain no prices, MOQ, lead time, full reports or confirmed lab values. Non-brand accounts cannot fetch full reports or values. Each verified email can create its own private supplier workspace and submit lot PDFs for review. A private supplier workspace does not create a public listing. Kasandrinos supplier and lot metadata use real source documents. Fictional supplier listings, lots and seeded Deal Rooms have been removed.</p><h3>Access codes</h3><p>Round two only. No codes are generated or redeemed in this prototype.</p></div>`}
function render(){closeExplore();let r=route();document.body.classList.toggle('storefront-view',r.startsWith('/suppliers/kasandrinos'));let content=r==='/proof'?proofWorkspace(session,render):r.startsWith('/organizations/')?organizationPage(proof.organizations.find(o=>o.slug===r.split('/').at(-1)),proof.organizations,allLots(state)):r.startsWith('/reports/')?reportGate(r,kasCatalog,session):r==='/team'?teamPage(session,render):mobileInformationPage(r)||informationPage(r)|| (sourcingRoutes(r)?sourcingPage(r,session,state.role,render,kasCatalog):r==='/'?home():r==='/brand'?brandHome():r==='/workspace'?supplierHome():r==='/workspace/documents'?documents():r==='/workspace/storefront'?editorPage(session):r==='/suppliers'?discovery():r.startsWith('/suppliers/kasandrinos')?kasPage():r.startsWith('/lots/')?proofLotPage(r.split('/').at(-1)):r==='/requests/new'?requestComposer():r==='/requests'?requestsPage():r==='/deals'?dealsPage():r.startsWith('/deals/')?roomPage(r==='/deals/room'?new URLSearchParams(location.search).get('id'):r.split('/').at(-1)):r==='/email-sign-in'?signIn():r==='/resources/labs/light-labs'?`${title('LABORATORY','Light Labs','Participating laboratory, per VLE confirmation.')}<div class="panel"><h2>Production issuer status pending verification</h2><p>Laboratory ordering and live TECRID authentication are not connected. A sample test is performed by a laboratory; TECRID authenticates the resulting evidence record.</p><a class="text-link" href="https://www.lightlabs.com/" target="_blank" rel="noreferrer">Official Light Labs website ↗</a></div>`:r==='/resources'?resources():r==='/design-system'?design():empty('Page not found.','Return to the exchange.','/','Home'));$('#app').innerHTML=mobileShell(state.role,session,r)+reviewBar()+`<div class="app-shell">${nav()}<div class="app-main">${topbar()}<main id="main">${r==='/notifications'?evidenceNotificationPanel():''}${content}${session.signedIn&&['/requests','/notifications'].includes(r)?'<section class="mobile-task-gap"><h2>No in-app access decisions yet</h2><p>TECRID access requests open in TECRID for approval or decline. VLE does not have access approval cards yet. Opening an alert does not grant access.</p><p>For supplier questions, open your conversation and reply there.</p><a href="/deals" data-nav class="button">Open conversations</a></section>':''}<div class="page-footer">${defaults(r==='/')}</div>${footer()}</main></div></div>`;save();if(r==='/workspace/storefront')mountStorefrontEditor(document.getElementById('storefront-editor'),kasCatalog,session,refresh);}
function go(url){close();closeExplore();history.pushState({},'',url);render();window.scrollTo(0,0);if(location.hash)document.getElementById(location.hash.slice(1))?.scrollIntoView()}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),5000)}
function open(title,body,wide=false){focusBack=document.activeElement;$('#dialog').className=wide?'wide-dialog':'';$('#dialog').innerHTML=`<div class="dialog-heading"><div><span class="eyebrow">VLE PROTOTYPE · EXAMPLE</span><h2 id="dialog-title">${title}</h2></div><button data-action="close" class="close" aria-label="Close dialog">×</button></div><div class="dialog-body">${body}<p class="form-error" id="form-error" role="alert"></p></div>`;$('#dialog').showModal();}
function close(){if($('#dialog').open)$('#dialog').close();if(pdfUrl){URL.revokeObjectURL(pdfUrl);pdfUrl=null;}focusBack?.isConnected&&focusBack.focus();}
async function coa(lot){if(state.role!=='brand'){go('/email-sign-in');return}await mutate('coa',{lot});const d=state.deals.find(x=>x.lot===lot),l=allLots(state).find(x=>x.id===lot);render();$('[data-action=coa][data-lot="'+lot+'"]')?.focus();open('Lot COA · '+l.id,`<div class="inline">${badge('Supplier-confirmed values')}${ex()}</div><p>${l.lab} · ${l.date} · ${l.basis}</p>${evidenceTable(l,state.limits)}<div class="notice">Your signed-in identity (${esc(session.email)}) is recorded for this COA view. The supplier review workspace can see who opened the report.</div><div class="form-actions"><button class="primary" data-action="pdf" data-lot="${lot}">Open EXAMPLE COA PDF ↗</button>${link('Continue in Deal Room',roomURL(d),'button orange')}</div><p class="fine">Synthetic lab document. No real report or credential is represented.</p>`,true)}
function stepDialog(id,step){const d=state.deals.find(x=>x.id===id);if(!canSeeDeal(state,d))throw Error('This room is not yours.');const l=allLots(state).find(x=>x.id===d.lot);let content='',title='';
if(step==='quote'){title='Share pricing';content=`<div class="form-grid">${field('USD per '+l.unit,'price',l.price,'number','min="0.01" step="any" required')}${field('MOQ in '+l.unit,'moq',l.moq,'number','min="1" required')}${field('Lead time','lead',l.lead,'text','required')}${field('Valid through','valid','2026-11-30','date','required')}</div>${field('Freight responsibility','freight','To agree','text','required')}<p class="fine">EXAMPLE quote. Taxes excluded. Not a binding landed price.</p>`;}
if(step==='sample'){title='Request a sample';content=`<div class="form-grid">${field('Sample quantity','quantity',250,'number','min="1" required')}${select('Unit','unit',['ml','g','kg','L'],l.unit==='L'?'ml':'g')}${field('Destination','destination',d.brief.destination,'text','required')}${field('Needed by','date',d.brief.date||'2026-11-30','date','required')}</div>${field('Intended use','use',d.brief.use,'text','required')}<p class="notice">Lot ${d.lot}. Shipping and verification-test responsibility must be agreed by both sides before shipment. No default payer.</p>`;}
if(step==='costs'){title='Agree who pays';content=`<p>Propose the payers. The other participant must accept the proposal.</p>${select('Sample shipping paid by','shipping',['Brand','Supplier','Split equally'])}${select('Verification test paid by','testing',['Brand','Supplier','Split equally'])}<p class="fine">No payer is preselected. Actual amounts remain subject to agreement; this prototype incurs no costs.</p>`;}
if(step==='ship'){title='Mark sample shipped';content=`<p>Sample from ${d.lot}. Both sides have agreed on cost responsibility.</p>${field('EXAMPLE shipment reference','tracking','EXAMPLE-SHIP-01','text','required')}${field('Dispatch date','date','2026-10-22','date','required')}<p class="fine">Creates a timeline event only. No carrier booking or real shipment.</p>`;}
if(step==='test'){title='Attach the sample result';content=`<p>Demonstrate the evidence handoff after the laboratory tests a sample. TECRID authenticates evidence records; it does not perform the test.</p>${field('Sample report lot','lot',d.lot,'text','required')}<div class="notice"><strong>EXAMPLE result and authentication state</strong><p>The fixture uses the same measurement basis and matching lot. No real TECRID code, test, signature or laboratory authentication is created.</p></div>`;}
if(step==='qualify'){title='Review the lot against your limits';content=`${evidenceTable({...l,values:d.test?.values||l.values},d.limits)}<p>${badge(match(l,d.limits),'green')}</p><label class="check"><input name="confirm" type="checkbox" required>I reviewed this matching EXAMPLE sample result and its basis against the brand’s saved limits.</label><p class="fine">Qualified is this brand’s EXAMPLE sourcing decision. It is not certification or a general safety claim.</p>`;}
if(step==='reserve'){title='Request a soft hold';content=`${field('Quantity in '+l.unit,'quantity',d.brief.quantity||l.moq,'number',`min="1" max="${l.amount}" required`)}${field('Hold until','until','2026-11-07','date','required')}<p class="notice">No payment or deposit. The supplier must confirm the hold. Contract and payment happen off the platform.</p>${def('Reservation is a soft hold with no payment.')}`;}
if(step==='confirm-reservation'){title='Confirm the soft hold';content=`<p>${brand.name} requested EXAMPLE ${d.reservation?.quantity} ${l.unit} until ${d.reservation?.until}.</p><p class="notice">This confirms a soft hold only. Contract and payment happen off the platform. No real inventory is reserved.</p>`;}
open(title,`<form data-form="step" data-id="${id}" data-step="${step}">${content}<div class="form-actions"><button type="button" class="secondary" data-action="close">Cancel</button><button type="submit" class="orange">${step==='costs'?'Propose payers':title} · EXAMPLE ${icon()}</button></div></form>`,step==='qualify');}
function requestDetail(id){const r=state.requests.find(x=>x.id===id);if(!r||state.role==='out'||state.role==='supplier'&&r.category!==supplierFor(state.supplier).category)throw Error('This Request is not available in your current view.');const eligible=allLots(state).filter(l=>l.supplier===state.supplier&&l.category===r.category);open(r.ingredient,`<div class="inline">${badge(r.status,'green')}${ex()}</div><p><strong>${brand.name}</strong> · ${r.quantity} ${r.unit} · ${esc(r.destination)}<br>Needed by ${r.date} · ${esc(r.use)}</p><p>${esc(r.needs)}</p><div class="compact-limits">${analytes.map((a,i)=>`<div><span>${a}</span><strong>≤ ${r.limits[i]} mg/kg</strong></div>`).join('')}</div><p class="fine">As-sold basis. Category-wide visibility. default, for review.</p>${state.role==='supplier'?eligible.length?`<form data-form="respond-request" data-id="${id}">${select('Respond with a COA-backed lot','lot',eligible.map(l=>l.id),eligible[0].id)}<label class="field"><span>Your response</span><textarea name="message" required rows="3">We can discuss this lot for your application. What would you like to evaluate first?</textarea></label><button class="orange" type="submit">Respond and open Deal Room ${icon()}</button></form>`:'<div class="notice">You need a matching lot COA and confirmed values before you can respond. Kasandrinos remains a draft.</div>':`<h3>Supplier responses</h3>${r.responses.length?r.responses.map(x=>state.deals.find(d=>d.id===x)).filter(Boolean).map(d=>link(supplierFor(d.supplier).name+' · Open room',roomURL(d),'button full')).join(''):'<p class="muted">No responses yet. Suppliers in '+r.category+' can see your Request.</p>'}${r.status==='Open'?action('Close Request','close-request',`data-id="${id}"`,'text-link'):''}`}`)}
document.addEventListener('click',async e=>{const anchor=e.target.closest('a[data-nav]');if(anchor){e.preventDefault();go(anchor.getAttribute('href'));return}const b=e.target.closest('[data-action]');if(!b)return;if(b.closest('form')&&b.tagName==='BUTTON')e.preventDefault();const a=b.dataset.action,id=b.dataset.id;try{switch(a){
case 'close':close();break;
case 'sign-out':{const response=await fetch('/api/auth/sign-out',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!response.ok)throw Error('Sign-out failed. Please try again.');location.assign('/');break;}
case 'workspace':await mutate('workspace',{role:b.dataset.role});invalidateSourcing();go(b.dataset.role==='supplier'?'/workspace':'/brand');break;
case 'role':if(!session.signedIn){go('/email-sign-in?as='+b.dataset.role);break}if(session.canReview)await mutate('role',{role:b.dataset.role});else if(b.dataset.role==='brand'&&session.canBuy)await mutate('workspace',{role:'brand'});if(b.dataset.role==='brand'&&!session.canBuy){go('/email-sign-in');break}go(b.dataset.role==='brand'?'/brand':'/workspace');break;
case 'reset':open('Reset your EXAMPLE workspace?',`<p>This restores your demonstration messages, Requests and progress. It does not delete evidence-access records.</p>${action('Reset my EXAMPLE state','reset-confirm','','orange')}`);break;
case 'reset-confirm':await mutate('reset');go('/');toast('Your EXAMPLE workspace was reset.');break;
case 'filter':filter=b.dataset.category;render();break;
case 'limits':open('Your saved contaminant limits',`<form data-form="limits"><p>mg/kg · as sold. These limits apply to future searches and new deals. Existing Deal Rooms retain their saved criteria.</p><div class="form-grid">${analytes.map((a,i)=>field(a,'limit'+i,state.limits[i],'number','min="0" step="any" required')).join('')}</div><button type="submit" class="primary">Save EXAMPLE limits</button></form>`);break;
case 'coa':await coa(b.dataset.lot);break;
case 'kas-report':{if(!session.signedIn){go('/email-sign-in');break}const r=await fetch('/api/reports/kasandrinos/'+encodeURIComponent(b.dataset.report),{cache:'no-store'});if(!r.ok)throw Error((await r.json()).error||'The report could not be opened.');const url=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=url;a.download='Kasandrinos-'+b.dataset.report+'.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('Original Kasandrinos report downloaded. Your evidence access was recorded.');break;}
case 'pdf':{const r=await fetch('/api/coa/'+encodeURIComponent(b.dataset.lot),{cache:'no-store'});if(!r.ok)throw Error((await r.json()).error);if(pdfUrl)URL.revokeObjectURL(pdfUrl);pdfUrl=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=pdfUrl;a.download=b.dataset.lot+'-COA-EXAMPLE.pdf';a.click();toast('Synthetic EXAMPLE PDF downloaded.');break;}
case 'inquiry':case 'start-sample':if(state.role!=='brand'){go('/email-sign-in');break}modal={lot:b.dataset.lot};open(a==='inquiry'?'Start the conversation':'Ask about a sample',`<form data-form="inquiry"><p>${brand.name} × ${supplierFor(allLots(state).find(l=>l.id===modal.lot).supplier).name}</p><label class="field"><span>Your message</span><textarea name="message" required rows="4">Could you share pricing and sample options for this lot?</textarea></label><p class="fine">One EXAMPLE Deal Room for your brand and this lot. No real supplier is contacted.</p><button class="orange" type="submit">Send EXAMPLE inquiry ${icon()}</button></form>`);break;
case 'request-detail':requestDetail(id);break;
case 'close-request':await mutate('close-request',{id});close();render();toast('EXAMPLE Request closed.');break;
case 'step':stepDialog(id,b.dataset.step);break;
case 'agree-costs':await mutate('transition',{id,step:'agree-costs',values:{}});render();toast('Cost responsibility agreed.');break;
case 'attach':open('Attach an EXAMPLE file',`<form data-form="attachment" data-id="${id}">${select('Fixture document','name',['Product-specification-EXAMPLE.txt','Packing-slip-EXAMPLE.txt'],'Product-specification-EXAMPLE.txt')}<p class="fine">Demonstration files only. No real confidential upload is accepted.</p><button type="submit" class="primary">Attach to shared timeline</button></form>`);break;
case 'download-attachment':if(!canSeeDeal(state,state.deals.find(d=>d.id===b.dataset.deal)))throw Error('This room is not yours.');const url=URL.createObjectURL(new Blob(['EXAMPLE fixture document. No real shipment, product specification or contractual data.'],{type:'text/plain'}));const el=document.createElement('a');el.href=url;el.download=b.dataset.name;el.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;
case 'load-coa':await mutate('load-coa');render();toast('EXAMPLE PDF loaded. Values await confirmation.');break;
case 'confirm-values':open('Confirm the extracted values',`<form data-form="confirm-values">${field('Specific lot','lot',state.draft.id,'text','required')}<p>EXAMPLE source PDF · page 1 · as sold. Confirm each value against the source.</p>${analytes.map((a,i)=>`<div class="confirm-row">${field(a+' in mg/kg','value'+i,state.draft.values[i],'number','min="0" step="any" required')}<label class="check"><input name="confirm${i}" type="checkbox" required>Confirm</label></div>`).join('')}<p class="fine">This fixture is for a fictional supplier, never Kasandrinos.</p><button class="orange" type="submit">Confirm and publish EXAMPLE lot</button></form>`);break;
}}catch(err){if($('#dialog').open)$('#form-error').textContent=err.message;else toast(err.message)}});
document.addEventListener('change',async e=>{try{if(e.target.id==='review-role'){await mutate('role',{role:e.target.value});close();if(['/brand','/workspace','/workspace/documents'].includes(route()))go(state.role==='brand'?'/brand':state.role==='supplier'?'/workspace':'/');else render();}if(e.target.id==='supplier-account'){await mutate('supplier',{supplier:e.target.value});close();render()}if(e.target.id==='only-match'){onlyMatch=e.target.checked;render()}}catch(err){toast(err.message);render()}});
document.addEventListener('submit',async e=>{const f=e.target;if(!f.dataset.form)return;e.preventDefault();const fd=new FormData(f),v=Object.fromEntries(fd.entries());try{switch(f.dataset.form){
case 'search':search=v.q;go('/suppliers?q='+encodeURIComponent(v.q));break;
case 'sign-in':{
 const button=f.querySelector('button[type=submit]'),result=$('#signin-result');button.disabled=true;result.textContent='Sending your sign-in link…';
 try{const response=await fetch('/api/auth/sign-in/magic-link',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:String(v.email).trim().toLowerCase(),callbackURL:reportReturnPath(new URLSearchParams(location.search).get('return_to'))||'/email-sign-in?as='+(v.workspace==='Supplier'?'supplier':'brand'),newUserCallbackURL:reportReturnPath(new URLSearchParams(location.search).get('return_to'))||'/email-sign-in?as='+(v.workspace==='Supplier'?'supplier':'brand'),errorCallbackURL:'/email-sign-in?as=brand&return_to='+encodeURIComponent(reportReturnPath(new URLSearchParams(location.search).get('return_to'))||'')})});
 if(!response.ok)throw Error(response.status===429?'Please wait a minute before requesting another link.':'We couldn’t send your link. Please try again shortly.');
 result.innerHTML='<div class="notice"><strong>Check your inbox.</strong><p>Your sign-in link is on its way. Open it to confirm your email. Check spam if it does not arrive.</p></div>';button.textContent='Send another link';
 }catch(error){result.textContent=error.message;}finally{button.disabled=false;}break;}

case 'supplier-profile':await mutate('supplier-profile',v);go('/workspace');break;
case 'limits':await mutate('limits',{limits:analytes.map((a,i)=>Number(v['limit'+i]))});close();render();break;
case 'post-request':await mutate('post-request',v);go('/requests');toast('EXAMPLE Request saved. No real supplier was contacted.');break;
case 'respond-request':await mutate('respond-request',{...v,id:f.dataset.id});go(roomURL(state.deals.find(d=>d.lot===v.lot)));break;
case 'inquiry':await mutate('inquiry',{...v,lot:modal.lot});go(roomURL(state.deals.find(d=>d.lot===modal.lot)));break;
case 'message':await mutate('transition',{id:f.dataset.id,step:'message',values:{text:v.text}});render();toast('EXAMPLE message added.');break;
case 'step':for(const k of ['price','moq','quantity'])if(k in v)v[k]=Number(v[k]);v.confirm=fd.has('confirm');await mutate('transition',{id:f.dataset.id,step:f.dataset.step,values:v});close();render();toast('EXAMPLE deal updated.');break;
case 'attachment':await mutate('attachment',{id:f.dataset.id,name:v.name});close();render();break;
case 'confirm-values':await mutate('confirm-values',{lot:v.lot,values:analytes.map((a,i)=>Number(v['value'+i])),confirmed:analytes.map((a,i)=>fd.has('confirm'+i))});close();render();toast('Confirmed EXAMPLE lot published in your review workspace.');break;
}}catch(err){const target=$('#form-error');if($('#dialog').open&&target)target.textContent=err.message;else toast(err.message)}});
window.addEventListener('popstate',()=>{close();render()});$('#dialog').addEventListener('cancel',e=>{e.preventDefault();close()});document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});
mountProof(async()=>{await refresh();render();});
